[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';Set-StrictMode -Version 2.0;$root=[IO.Path]::GetFullPath($Path);$meta=Get-Content (Join-Path $root 'synthetic-bc-basic.json') -Raw|ConvertFrom-Json;if($meta.product_id -ne 'spectra' -or $meta.synthetic -ne $true -or $meta.installable -ne $false -or $meta.release_status -ne 'PENDING_BCPROJECTOS_RELEASE'){throw 'BC_BASIC_IDENTITY_INVALID'};foreach($area in @('sales','purchasing','inventory','finance')){if(-not(Test-Path (Join-Path $root $area) -PathType Container)){throw "BC_BASIC_AREA_MISSING:$area"}};$expected=@('initialization','planning','setup','migration','process_execution','test_uat','evidence','cutover','hypercare','handover');if(@($meta.process_chain).Count -ne $expected.Count -or (Compare-Object $expected @($meta.process_chain))){throw 'BC_BASIC_PROCESS_CHAIN_INVALID'};$records=Get-Content (Join-Path $root 'projects\records.json') -Raw|ConvertFrom-Json;if(@($records).Count -ne 3){throw 'BC_BASIC_RECORD_COUNT_INVALID'};foreach($r in @($records)){if([string]$r.status -notin @('draft','active')){throw "BC_BASIC_STATUS_INVALID:$($r.id)"}};$gates=Get-Content (Join-Path $root 'evidence\simulated-gates.json') -Raw|ConvertFrom-Json;if(@($gates).Count -ne 13){throw 'BC_BASIC_SIMULATED_GATE_COUNT_INVALID'};foreach($g in @($gates)){if($g.status -ne 'simulated_pass' -or $g.synthetic -ne $true -or $g.external_activity -ne $false){throw "BC_BASIC_SIMULATED_GATE_INVALID:$($g.gate)"}};Write-Host 'PASS: Synthetic BC-Basic workspace and simulated execution gates validate read-only.'
